      }
    ],
    "lacunas": [],
    "motivo": "A linha base declarada fixa o término em D12.",
    "unidade": "dia_corrido"
  },
  "fim_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_f2afea",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "A nova duração de usinar corpo pode ser qualquer inteiro não negativo.",
      "As precedências estão referenciadas em uma ficha não incluída na view."
    ],
    "motivo": "Sem a duração definida e sem suporte visível para as precedências, não é possível determinar o término após o aviso.",
    "unidade": "dia_corrido"
  },
  "delta_dias": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      },
      {
        "fonte_id": "f_f2afea",
        "localizador": "L01"
      }
    ],
    "lacunas": [
      "A variação depende da duração nova de usinar corpo e das precedências não visíveis."
    ],
    "motivo": "O término base é D12, mas não há suporte suficiente para comparar com um término novo determinado ou para afirmar a direção da variação.",
    "unidade": "dia_corrido"
  },
  "custo_base": {
    "estado": "exato",
    "valor": 165000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [],
    "motivo": "A linha base declarada fixa o custo em R$ 1.650,00.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_f2afea",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      }
    ],
    "lacunas": [
      "O valor total depende do término novo, que pode alterar a extensão cobrada do apoio."
    ],
    "motivo": "O aviso acrescenta uma cobrança certa de R$ 25,00, mas o custo final pode incluir extensão adicional do apoio e sua magnitude não é determinável.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "direcao",
    "valor": null,
    "direcao": "aumento",
    "evidencias": [
      {
        "fonte_id": "f_f2afea",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      }
    ],
    "lacunas": [
      "A magnitude total depende de eventual extensão do apoio após D12."
    ],
    "motivo": "A cobrança adicional obrigatória é de R$ 25,00; a política sem crédito impede reduzir o apoio por antecipação, e eventual atraso pode aumentar sua extensão.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "A linha base fornece D12 e R$ 1.650,00. O aviso fixa uma cobrança adicional de R$ 25,00, mas deixa indeterminada a nova duração de usinar corpo. Como as precedências referenciadas não estão visíveis, não é possível estimar o novo término nem quantificar eventual extensão adicional do apoio."
}

